<?php require_once __DIR__.'/auth.php'; api_auth(); header('Content-Type: application/json');$f=__DIR__.'/enquiries.json';$rows=file_exists($f)?json_decode(file_get_contents($f),true):[];if(!is_array($rows))$rows=[];$a=$_GET['action']??$_POST['action']??'list';if($a==='list'){echo json_encode($rows);exit;}if($a==='export'){header('Content-Type:text/csv');header('Content-Disposition:attachment;filename=enquiries.csv');$o=fopen('php://output','w');fputcsv($o,['Name','Phone','Email','Interest','Message','Created','Read']);foreach($rows as $r)fputcsv($o,[$r['name']??'', $r['phone']??'', $r['email']??'', $r['interest']??'', $r['message']??'', $r['created_at']??'', !empty($r['is_read'])?'Yes':'No']);exit;}if(in_array($a,['read','unread','delete'],true)){ $id=(int)($_POST['id']??0);if($a==='delete')$rows=array_values(array_filter($rows,fn($r)=>(int)$r['id']!==$id));else foreach($rows as &$r)if((int)$r['id']===$id)$r['is_read']=$a==='read';file_put_contents($f,json_encode($rows,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),LOCK_EX);echo json_encode(['ok'=>true]);exit;}http_response_code(400);echo json_encode(['error'=>'Unknown action']);
